Definition rodata_clear (mem : word -> option byte) : Prop :=
  forall i, (0x10390 <= i < 0x103b0)%Z -> mem (Z_to_bv 64 i) = None.

Lemma rd_const_M : forall mem, rodata_clear mem ->
